struct SearchField {                    // the widget owns its state
    std::string query;

    void on_key(std::string_view value) {
        query.assign(value);            // written where it is used
    }
};

SearchField field;                      // state lives and dies with the object
field.on_key("ab");

// SearchField.qml - the state cell lives in the component that uses it
import QtQuick

Item {
    id: root
    property string query: ""          // component-local state

    TextInput {
        text: root.query
        onTextEdited: root.query = text
    }
    Text { text: "searching: " + root.query }   // derived by binding
}

